"""Atomic SQLite snapshots, immutable plans and durable cross-source recovery evidence."""

import json
import sqlite3
from pathlib import Path

from .models import MANIFEST_FIELDS, Run, compare, summarize, timestamp
from .reconcile import (
    attach_recovered,
    known_score,
    official_result,
    original_result,
    preserve_recovered,
    recovered_result,
)


class Conflict(ValueError):
    pass


class Store:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS runs (
                    run_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, body TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS sessions (
                    arena TEXT NOT NULL, session_id TEXT NOT NULL, run_id TEXT NOT NULL,
                    PRIMARY KEY(arena, session_id)
                );
            """)

    def _connect(self):
        return sqlite3.connect(self.path, timeout=10)

    @staticmethod
    def _write(db, body):
        validated = Run.model_validate(body).model_dump()
        db.execute(
            "INSERT INTO runs VALUES (?, ?, ?) ON CONFLICT(run_id) DO UPDATE SET "
            "revision=excluded.revision, body=excluded.body",
            (validated["run_id"], validated["revision"], json.dumps(validated, allow_nan=False)),
        )

    @staticmethod
    def _add_recovery(db, owner: dict, session_id: str, outcome: dict) -> bool:
        for attempt in owner["attempts"]:
            if attempt["session_id"] == session_id and attach_recovered(attempt, outcome):
                # Keep the laptop writer's revision and timestamps. Polling recovered-count detects
                # this additive change without making its next numbered upload stale.
                Store._write(db, owner)
                return True
        return False

    def reconcile(self, run_id: str, session_id: str, outcome: dict) -> bool:
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            row = db.execute("SELECT body FROM runs WHERE run_id=?", (run_id,)).fetchone()
            return self._add_recovery(db, json.loads(row[0]), session_id, outcome) if row else False

    def _check_previous(self, previous: dict, body: dict):
        if any(previous[key] != body[key] for key in MANIFEST_FIELDS):
            raise Conflict("run manifest is immutable")
        if previous["status"] != "running" and body["status"] == "running":
            raise Conflict("run status cannot regress")
        old_attempts = {a["attempt_id"]: a for a in previous["attempts"]}
        for attempt in body["attempts"]:
            before = old_attempts.get(attempt["attempt_id"])
            if before is None or (before["session_id"] and before["session_id"] != attempt["session_id"]):
                raise Conflict("attempt identity is immutable")
            preserve_recovered(before, attempt)
            imported_retry = (
                body["source"] == "imported"
                and before["score"] is None
                and attempt["status"] == "completed"
                and known_score(attempt["score"])
                and before["error"] == attempt["error"]
            )
            if before["status"] in {"completed", "failed"} and not imported_retry:
                if (
                    before["status"] != attempt["status"]
                    or before["score"] != attempt["score"]
                    or original_result(before["result"]) != original_result(attempt["result"])
                ):
                    raise Conflict("finished attempts are immutable")

    def upsert(self, run: Run) -> bool:
        body = run.model_dump()
        try:
            with self._connect() as db:
                db.execute("BEGIN IMMEDIATE")
                old = db.execute("SELECT revision, body FROM runs WHERE run_id=?", (run.run_id,)).fetchone()
                if old and old[0] >= run.revision:
                    previous = json.loads(old[1])
                    if all(previous[key] == body[key] for key in MANIFEST_FIELDS):
                        for attempt in body["attempts"]:
                            outcome = recovered_result(attempt)
                            if attempt["session_id"] and outcome:
                                self._add_recovery(db, previous, attempt["session_id"], outcome)
                    return False
                if old:
                    self._check_previous(json.loads(old[1]), body)
                sessions = [a["session_id"] for a in body["attempts"] if a["session_id"]]
                if len(set(sessions)) != len(sessions):
                    raise Conflict("duplicate arena session")
                replaced_imports = set()
                for attempt in body["attempts"]:
                    session = attempt["session_id"]
                    if not session:
                        continue
                    owner = db.execute(
                        "SELECT run_id FROM sessions WHERE arena=? AND session_id=?", (run.arena_url, session)
                    ).fetchone()
                    if not owner or owner[0] == run.run_id:
                        continue
                    owner_body = json.loads(
                        db.execute("SELECT body FROM runs WHERE run_id=?", (owner[0],)).fetchone()[0]
                    )
                    if run.source == "imported":
                        outcome = official_result(attempt)
                        if outcome:
                            self._add_recovery(db, owner_body, session, outcome)
                        return False
                    if owner_body["source"] != "imported" or len(owner_body["attempts"]) != 1:
                        raise Conflict("arena session already belongs to a run")
                    outcome = official_result(owner_body["attempts"][0])
                    if outcome:
                        attach_recovered(attempt, outcome)
                    replaced_imports.add(owner[0])
                # Preserve every official history outcome before restoring tracked provenance.
                # Later active/failure uploads inherit it without changing their original metrics.
                Run.model_validate(body)
                for owner_id in replaced_imports:
                    db.execute("DELETE FROM sessions WHERE run_id=?", (owner_id,))
                    db.execute("DELETE FROM runs WHERE run_id=?", (owner_id,))
                for session in sessions:
                    db.execute("INSERT OR IGNORE INTO sessions VALUES (?, ?, ?)", (run.arena_url, session, run.run_id))
                self._write(db, body)
        except ValueError as error:
            if isinstance(error, Conflict):
                raise
            raise Conflict("invalid or conflicting recovery evidence") from None
        return True

    def get(self, run_id: str) -> dict | None:
        with self._connect() as db:
            row = db.execute("SELECT body FROM runs WHERE run_id=?", (run_id,)).fetchone()
        return json.loads(row[0]) if row else None

    def all(self) -> list[Run]:
        with self._connect() as db:
            rows = db.execute("SELECT body FROM runs ORDER BY json_extract(body, '$.started_at') DESC").fetchall()
        return [Run.model_validate(json.loads(row[0])) for row in rows]

    def listing(self) -> dict:
        runs = self.all()
        quotas = [r.quota for r in runs if r.quota]
        latest = max(quotas, key=lambda q: timestamp(q.checked_at)) if quotas else None
        return {
            "runs": [summarize(run) for run in runs],
            "quota": latest.model_dump() if latest else None,
            "team": "y/agent",
        }

    def comparison(self, baseline: str, candidate: str) -> dict | None:
        left, right = self.get(baseline), self.get(candidate)
        return compare(Run.model_validate(left), Run.model_validate(right)) if left and right else None
"""Strict public loop records, independent of execution and transport."""

from typing import Any, Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .models import check_json

ID = str


class Record(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, allow_inf_nan=False)

    @model_validator(mode="after")
    def safe_json(self):
        check_json(self.model_dump())
        for name, value in self.model_dump().items():
            if name.endswith("_id") and value is not None:
                import re

                if not re.fullmatch(r"[A-Za-z0-9_.:-]{1,240}", value):
                    raise ValueError("invalid identity")
        return self


class Policy(Record):
    version: str = "v1"
    min_gain: float = Field(default=1.0, ge=1)
    max_case_regression: float = Field(default=2.0, ge=0, le=2)
    min_win_fraction: float = Field(default=2 / 3, ge=2 / 3, le=1)


class Suite(Record):
    suite_id: ID
    cases: list[str] = Field(min_length=1, max_length=100)
    repetitions: int = Field(ge=3, le=100)
    runner: Literal["serial", "async"]
    arena_url: str
    environment: Literal["sandbox", "practice", "simulator"]
    data: dict[str, Any]
    max_sessions: int = Field(ge=1, le=20000)
    policy: Policy

    @model_validator(mode="after")
    def coherent(self):
        url = urlsplit(self.arena_url)
        if (
            url.scheme not in ("https", "http")
            or not url.hostname
            or url.username
            or url.password
            or url.query
            or url.fragment
        ):
            raise ValueError("invalid arena origin")
        if url.path not in ("", "/") or len(set(self.cases)) != len(self.cases):
            raise ValueError("invalid cases or arena origin")
        if self.max_sessions != 2 * len(self.cases) * self.repetitions:
            raise ValueError("session ceiling differs from exact plan")
        # HTTP origin aliases must share quota reservations and session ownership.
        host = url.hostname.lower()
        if ":" in host:
            host = "[" + host + "]"
        port = url.port
        suffix = "" if port is None or port == {"http": 80, "https": 443}[url.scheme] else f":{port}"
        self.arena_url = f"{url.scheme}://{host}{suffix}"
        return self


class Family(Record):
    family_id: ID
    max_sessions: int = Field(ge=1, le=100000)
    practice_allowance: int = Field(default=0, ge=0)
    reserve: int = Field(default=0, ge=0)


class Quota(Record):
    remaining: int = Field(ge=0)
    observed_at: float = Field(ge=0)
    open_sessions: int = Field(default=0, ge=0)


class Campaign(Record):
    campaign_id: ID
    family_id: ID
    suite_id: ID
    baseline_id: ID
    candidate_id: ID
    generation: int = Field(ge=1)
    seed: int
    author: str = Field(min_length=1, max_length=200)
    hypothesis: str = Field(min_length=1, max_length=4000)
    quota: Quota | None = None


class Recommendation(Record):
    suite_id: ID
    checkpoint_id: ID
    author: str = Field(min_length=1, max_length=200)
    request_id: ID | None = None
    generation: int | None = Field(default=None, ge=1)


class Start(Record):
    attempt_id: ID
    worker_id: ID
    key_id: ID
    quota: Quota | None = None


class Outcome(Record):
    attempt_id: ID
    checkpoint_id: ID
    session_id: ID | None
    status: Literal["completed", "failed", "ambiguous", "recovered"]
    score: float | None = Field(default=None, ge=0, le=1)
    timeouts: int | None = Field(default=None, ge=0)
    result: dict[str, Any] = Field(default_factory=dict)
    threads: dict[str, Any] = Field(default_factory=dict)
    elapsed_s: float | None = Field(default=None, ge=0)


class Complete(Record):
    campaign_id: ID


class Finding(Record):
    finding_id: ID
    campaign_id: ID
    candidate_id: ID
    author: str = Field(min_length=1, max_length=200)
    observation: str = Field(min_length=1, max_length=4000)
    hypothesis: str = Field(min_length=1, max_length=4000)
    change: str = Field(min_length=1, max_length=4000)
    next_test: str = Field(min_length=1, max_length=4000)
    confidence: float = Field(ge=0, le=1)
    disposition: Literal["proposed", "accepted", "rejected", "tested"]
    evidence: list[dict[str, Any]] = Field(min_length=1, max_length=100)


class Reconciliation(Record):
    attempt_id: ID
    checkpoint_id: ID
    session_id: ID
    result: dict[str, Any]
    threads: dict[str, Any] = Field(default_factory=dict)
    score: float | None = Field(default=None, ge=0, le=1)
    timeouts: int | None = Field(default=None, ge=0)

    @model_validator(mode="after")
    def ended(self):
        if self.result.get("ended") is not True:
            raise ValueError("owned ended session evidence required")
        return self


class NotCreated(Record):
    worker_id: ID
    attempt_id: ID
    checkpoint_id: ID
    reason: Literal["worker_preflight", "arena_rejected"]
    http_status: int | None = None

    @model_validator(mode="after")
    def definite(self):
        if self.reason == "worker_preflight" and self.http_status is not None:
            raise ValueError("preflight cannot include HTTP status")
        if self.reason == "arena_rejected" and self.http_status not in (400, 401, 403, 404, 422, 429):
            raise ValueError("definite session create rejection required")
        return self

"""Transactional loop metadata; laptops execute code and report owned evidence."""

import json
import sqlite3
import time
from pathlib import Path

from .checkpoints import validate_checkpoint
from .evidence import validate_references
from .loop_models import (
    Campaign,
    Complete,
    Family,
    Finding,
    NotCreated,
    Outcome,
    Recommendation,
    Reconciliation,
    Start,
    Suite,
)
from .ordering import campaign_order
from .policy import evaluate_campaign
from .store import Conflict


class LoopStore:
    def __init__(self, path: Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS loop_records (
                    kind TEXT NOT NULL, id TEXT NOT NULL, body TEXT NOT NULL,
                    PRIMARY KEY(kind,id));
                CREATE TABLE IF NOT EXISTS loop_sessions (
                    arena TEXT NOT NULL, session_id TEXT NOT NULL, attempt_id TEXT NOT NULL,
                    PRIMARY KEY(arena,session_id));
                CREATE TABLE IF NOT EXISTS loop_leases (
                    key_id TEXT PRIMARY KEY, attempt_id TEXT, last_start REAL NOT NULL);
            """)

    def _connect(self):
        return sqlite3.connect(self.path, timeout=10)

    @staticmethod
    def _get(db, kind, key):
        row = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
        if not row:
            raise ValueError("record not found")
        return json.loads(row[0])

    @staticmethod
    def _all(db, kind):
        records = [
            json.loads(r[0]) for r in db.execute("SELECT body FROM loop_records WHERE kind=? ORDER BY id", (kind,))
        ]
        if kind == "history":
            records.sort(key=lambda event: (event["recommendation"]["updated_at"], event["event_id"]))
        return records

    @staticmethod
    def _put(db, kind, key, body, immutable=False):
        encoded = json.dumps(body, sort_keys=True, allow_nan=False)
        row = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
        if immutable and row and json.loads(row[0]) != body:
            raise Conflict("immutable record conflict")
        db.execute(
            "INSERT INTO loop_records VALUES(?,?,?) ON CONFLICT(kind,id) DO UPDATE SET body=excluded.body",
            (kind, key, encoded),
        )
        return body

    def _checkpoint(self, db, suite, key):
        checkpoint = self._get(db, "checkpoints", key)
        if (
            not checkpoint["published"]
            or checkpoint["runner"] != suite["runner"]
            or checkpoint["data"] != suite["data"]
        ):
            raise ValueError("checkpoint unavailable or execution inputs differ")
        return checkpoint

    def _practice(self, db, suite, family, quota, *, starting=False):
        if suite["environment"] != "practice":
            return
        if not family["practice_allowance"] or quota is None or not 0 <= time.time() - quota["observed_at"] <= 60:
            raise ValueError("practice allowance and fresh quota required")
        campaigns = self._all(db, "campaigns")
        active = sum(
            sum(a["status"] == "pending" for a in c["attempts"])
            for c in campaigns
            if self._get(db, "suites", c["suite_id"])["arena_url"] == suite["arena_url"]
            and self._get(db, "suites", c["suite_id"])["environment"] == "practice"
        )
        required = 0 if starting else suite["max_sessions"]
        reserve = max([family["reserve"]] + [f["reserve"] for f in self._all(db, "families")])
        if quota["remaining"] - quota["open_sessions"] - active - required < reserve:
            raise ValueError("protected practice reserve")
        if not starting and family["practice_reserved"] + required > family["practice_allowance"]:
            raise ValueError("practice allowance exhausted")

    def write(self, operation: str, body: dict) -> dict:
        models = {
            "suite": Suite,
            "family": Family,
            "campaign": Campaign,
            "seed": Recommendation,
            "restore": Recommendation,
            "attempt-start": Start,
            "attempt-result": Outcome,
            "attempt-reconcile": Reconciliation,
            "attempt-not-created": NotCreated,
            "complete": Complete,
            "finding": Finding,
        }
        if operation == "checkpoint":
            body = validate_checkpoint(body)
        elif operation in models:
            body = models[operation].model_validate(body).model_dump()
        else:
            raise ValueError("unknown operation")
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            if operation in ("checkpoint", "suite", "family"):
                kind = {"checkpoint": "checkpoints", "suite": "suites", "family": "families"}[operation]
                key = body[operation + "_id"]
                if operation == "family":
                    body.update(reserved_sessions=0, practice_reserved=0)
                    existing = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
                    if existing:
                        old = json.loads(existing[0])
                        body.update(
                            reserved_sessions=old["reserved_sessions"], practice_reserved=old["practice_reserved"]
                        )
                return self._put(db, kind, key, body, immutable=True)
            if operation in ("seed", "restore"):
                suite = self._get(db, "suites", body["suite_id"])
                self._checkpoint(db, suite, body["checkpoint_id"])
                if operation == "restore" and not body["request_id"]:
                    raise ValueError("restore request ID required")
                if operation == "restore" and not any(
                    h["suite_id"] == body["suite_id"] and h["checkpoint_id"] == body["checkpoint_id"]
                    for h in self._all(db, "history")
                ):
                    raise ValueError("restore target was never recommended")
                event_id = body["request_id"] or "seed:" + body["suite_id"]
                previous_event = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("history", event_id)
                ).fetchone()
                if previous_event:
                    event = json.loads(previous_event[0])
                    if event.get("request") != body:
                        raise Conflict("recommendation request conflict")
                    return event["recommendation"]
                old = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("recommended", body["suite_id"])
                ).fetchone()
                old = json.loads(old[0]) if old else None
                if (
                    operation == "seed"
                    and old
                    or operation == "restore"
                    and (not old or body["generation"] != old["generation"])
                ):
                    raise Conflict("recommendation generation conflict")
                return self._recommend(db, suite, body["checkpoint_id"], old, event_id, operation, request=body)
            if operation == "campaign":
                previous = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("campaigns", body["campaign_id"])
                ).fetchone()
                if previous:
                    previous = json.loads(previous[0])
                    if previous["request"] != body:
                        raise Conflict("campaign ID conflict")
                    return previous
                suite = self._get(db, "suites", body["suite_id"])
                family = self._get(db, "families", body["family_id"])
                rec = self._get(db, "recommended", body["suite_id"])
                if rec["generation"] != body["generation"] or rec["checkpoint_id"] != body["baseline_id"]:
                    raise Conflict("baseline superseded")
                for key in ("baseline_id", "candidate_id"):
                    self._checkpoint(db, suite, body[key])
                if family["reserved_sessions"] + suite["max_sessions"] > family["max_sessions"]:
                    raise ValueError("family budget exhausted")
                self._practice(db, suite, family, body["quota"])
                attempts = []
                for cell in campaign_order(suite["cases"], suite["repetitions"], body["seed"]):
                    arm, case, repeat = cell["arm"], cell["case_id"], cell["repeat"]
                    case_index = suite["cases"].index(case)
                    attempts.append(
                        dict(
                            attempt_id=f"{body['campaign_id']}:{case_index}:{repeat}:{arm}",
                            **cell,
                            checkpoint_id=body[arm + "_id"],
                            status="pending",
                        )
                    )
                family["reserved_sessions"] += suite["max_sessions"]
                if suite["environment"] == "practice":
                    family["practice_reserved"] += suite["max_sessions"]
                self._put(db, "families", family["family_id"], family)
                campaign = {
                    **body,
                    "request": body,
                    "attempts": attempts,
                    "status": "running",
                    "created_at": time.time(),
                }
                return self._put(db, "campaigns", body["campaign_id"], campaign)
            if operation == "attempt-not-created":
                campaign, attempt = self._attempt(db, body["attempt_id"])
                if "start" not in attempt or attempt["checkpoint_id"] != body["checkpoint_id"]:
                    raise ValueError("not-created attempt mismatch")
                if attempt["start"]["request"]["worker_id"] != body["worker_id"]:
                    raise Conflict("not-created evidence executor mismatch")
                if attempt.get("session_id") or attempt.get("reconciliation"):
                    raise Conflict("known session cannot be declared not created")
                if "not_created" in attempt:
                    if attempt["not_created"] != body:
                        raise Conflict("immutable not-created evidence conflict")
                    return attempt
                if attempt["status"] not in ("started", "failed"):
                    raise Conflict("not-created evidence requires started or failed attempt")
                attempt.update(status="failed", not_created=body)
                db.execute("UPDATE loop_leases SET attempt_id=NULL WHERE attempt_id=?", (body["attempt_id"],))
                self._put(db, "campaigns", campaign["campaign_id"], campaign)
                return attempt
            if operation in ("attempt-start", "attempt-result", "attempt-reconcile"):
                campaign, attempt = self._attempt(db, body["attempt_id"])
                suite = self._get(db, "suites", campaign["suite_id"])
                if campaign["status"] != "running" and operation == "attempt-start":
                    raise Conflict("campaign already completed")
                if operation == "attempt-reconcile":
                    if "start" not in attempt or attempt["checkpoint_id"] != body["checkpoint_id"]:
                        raise ValueError("reconciliation attempt mismatch")
                    if attempt.get("session_id") not in (None, body["session_id"]):
                        raise Conflict("reconciliation session mismatch")
                    if "reconciliation" in attempt:
                        if attempt["reconciliation"] != body:
                            raise Conflict("immutable reconciliation conflict")
                        return attempt
                    row = db.execute(
                        "SELECT attempt_id FROM loop_sessions WHERE arena=? AND session_id=?",
                        (suite["arena_url"], body["session_id"]),
                    ).fetchone()
                    if row and row[0] != body["attempt_id"]:
                        raise Conflict("session already belongs to another attempt")
                    db.execute(
                        "INSERT OR IGNORE INTO loop_sessions VALUES(?,?,?)",
                        (suite["arena_url"], body["session_id"], body["attempt_id"]),
                    )
                    # Add recovered evidence, retaining the original execution status and score.
                    if attempt["status"] == "started":
                        attempt["status"] = "ambiguous"
                    attempt["reconciliation"] = body
                    db.execute("UPDATE loop_leases SET attempt_id=NULL WHERE attempt_id=?", (body["attempt_id"],))
                    self._put(db, "campaigns", campaign["campaign_id"], campaign)
                    return attempt
                if operation == "attempt-start":
                    if "start" in attempt:
                        if attempt["start"]["request"] != body:
                            raise Conflict("attempt start conflict")
                        return attempt
                    if attempt["status"] != "pending":
                        raise Conflict("attempt is terminal")
                    family = self._get(db, "families", campaign["family_id"])
                    self._practice(db, suite, family, body["quota"], starting=True)
                    lease = db.execute(
                        "SELECT attempt_id,last_start FROM loop_leases WHERE key_id=?", (body["key_id"],)
                    ).fetchone()
                    now = time.time()
                    if lease and lease[0] is not None:
                        raise Conflict("hosted start already owned")
                    # Sandbox has no quota pacing requirement; practice uses a key-wide interval.
                    if lease and suite["environment"] == "practice" and now - lease[1] < 1:
                        raise Conflict("hosted start pacing")
                    db.execute(
                        "INSERT INTO loop_leases VALUES(?,?,?) ON CONFLICT(key_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,last_start=excluded.last_start",
                        (body["key_id"], body["attempt_id"], now),
                    )
                    attempt.update(status="started", start={"request": body, "started_at": now})
                else:
                    if attempt["checkpoint_id"] != body["checkpoint_id"]:
                        raise ValueError("attempt checkpoint mismatch")
                    if "outcome" in attempt:
                        if attempt["outcome"] != body:
                            raise Conflict("terminal outcome conflict")
                        return attempt
                    if "start" not in attempt:
                        raise ValueError("attempt not started")
                    if attempt["status"] != "started":
                        raise Conflict("original execution outcome is already terminal")
                    if "reconciliation" in attempt and body["session_id"] != attempt["reconciliation"]["session_id"]:
                        raise Conflict("known session identity conflict")
                    if body["status"] in ("completed", "recovered") and not body["session_id"]:
                        raise ValueError("known outcome requires session ID")
                    if body["session_id"]:
                        row = db.execute(
                            "SELECT attempt_id FROM loop_sessions WHERE arena=? AND session_id=?",
                            (suite["arena_url"], body["session_id"]),
                        ).fetchone()
                        if row and row[0] != body["attempt_id"]:
                            raise Conflict("session already belongs to another attempt")
                        db.execute(
                            "INSERT OR IGNORE INTO loop_sessions VALUES(?,?,?)",
                            (suite["arena_url"], body["session_id"], body["attempt_id"]),
                        )
                    attempt.update(body, outcome=body)
                    if body["session_id"] and body["result"].get("ended") is True:
                        db.execute("UPDATE loop_leases SET attempt_id=NULL WHERE attempt_id=?", (body["attempt_id"],))
                self._put(db, "campaigns", campaign["campaign_id"], campaign)
                return attempt
            if operation == "complete":
                campaign = self._get(db, "campaigns", body["campaign_id"])
                if "completion" in campaign:
                    return campaign["completion"]
                if any(a["status"] in ("pending", "started") for a in campaign["attempts"]):
                    raise Conflict("campaign has unfinished planned attempts")
                suite = self._get(db, "suites", campaign["suite_id"])
                evaluation = evaluate_campaign(
                    suite,
                    self._get(db, "checkpoints", campaign["baseline_id"]),
                    self._get(db, "checkpoints", campaign["candidate_id"]),
                    campaign["attempts"],
                )
                old = self._get(db, "recommended", suite["suite_id"])
                if old["generation"] != campaign["generation"] or old["checkpoint_id"] != campaign["baseline_id"]:
                    status = "baseline_superseded"
                elif evaluation["eligible"]:
                    status = "promoted"
                    self._recommend(
                        db,
                        suite,
                        campaign["candidate_id"],
                        old,
                        "promotion:" + campaign["campaign_id"],
                        "promotion",
                        campaign_id=campaign["campaign_id"],
                        evaluation=evaluation,
                    )
                else:
                    status = (
                        "insufficient_evidence"
                        if any(
                            g in evaluation["evidence_gaps"]
                            for g in ("complete_sample", "must_haves", "timeout_evidence")
                        )
                        else "rejected"
                    )
                completion = dict(campaign_id=campaign["campaign_id"], status=status, evaluation=evaluation)
                campaign.update(status=status, completion=completion)
                self._put(db, "campaigns", campaign["campaign_id"], campaign)
                return completion
            if operation == "finding":
                campaign = self._get(db, "campaigns", body["campaign_id"])
                if campaign["candidate_id"] != body["candidate_id"]:
                    raise ValueError("finding candidate mismatch")
                validate_references(body["evidence"], campaign["attempts"])
                return self._put(db, "findings", body["finding_id"], body, immutable=True)
        raise ValueError("unknown operation")

    def _attempt(self, db, key):
        for campaign in self._all(db, "campaigns"):
            for attempt in campaign["attempts"]:
                if attempt["attempt_id"] == key:
                    return campaign, attempt
        raise ValueError("attempt not found")

    def _recommend(self, db, suite, checkpoint_id, old, event_id, action, **metadata):
        rec = dict(
            suite_id=suite["suite_id"],
            checkpoint_id=checkpoint_id,
            generation=old["generation"] + 1 if old else 1,
            updated_at=time.time(),
            event_id=event_id,
        )
        event = dict(
            event_id=event_id,
            action=action,
            previous_id=old["checkpoint_id"] if old else None,
            checkpoint_id=checkpoint_id,
            suite_id=suite["suite_id"],
            recommendation=rec,
            **metadata,
        )
        self._put(db, "history", event_id, event, immutable=True)
        self._put(db, "recommended", suite["suite_id"], rec)
        return rec

    def read(self, resource: str, key: str | None = None) -> dict:
        if resource not in (
            "checkpoints",
            "suites",
            "families",
            "campaigns",
            "recommended",
            "history",
            "findings",
            "evidence",
            "overview",
        ):
            raise ValueError("unknown resource")
        with self._connect() as db:
            if resource == "evidence":
                if key is None:
                    raise ValueError("evidence requires attempt ID")
                campaign, attempt = self._attempt(db, key)
                return dict(campaign_id=campaign["campaign_id"], attempt=attempt)
            if resource == "overview":
                campaigns = self._all(db, "campaigns")
                return dict(
                    suites=self._all(db, "suites"),
                    recommended=self._all(db, "recommended"),
                    families=self._all(db, "families"),
                    history=self._all(db, "history"),
                    campaigns=[
                        {k: v for k, v in c.items() if k not in ("attempts", "request", "quota")} for c in campaigns
                    ],
                    findings=self._all(db, "findings"),
                )
            if key is not None:
                return self._get(db, resource, key)
            return {resource: self._all(db, resource)}

"""Atomic SQLite snapshots, immutable plans and durable cross-source recovery evidence."""

import json
import sqlite3
from pathlib import Path

from .models import MANIFEST_FIELDS, Run, compare, summarize, timestamp
from .reconcile import (
    attach_recovered,
    known_score,
    official_result,
    original_result,
    preserve_recovered,
    recovered_result,
)


class Conflict(ValueError):
    pass


class Store:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS runs (
                    run_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, body TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS sessions (
                    arena TEXT NOT NULL, session_id TEXT NOT NULL, run_id TEXT NOT NULL,
                    PRIMARY KEY(arena, session_id)
                );
            """)

    def _connect(self):
        return sqlite3.connect(self.path, timeout=10)

    @staticmethod
    def _write(db, body):
        validated = Run.model_validate(body).model_dump()
        db.execute(
            "INSERT INTO runs VALUES (?, ?, ?) ON CONFLICT(run_id) DO UPDATE SET "
            "revision=excluded.revision, body=excluded.body",
            (validated["run_id"], validated["revision"], json.dumps(validated, allow_nan=False)),
        )

    @staticmethod
    def _add_recovery(db, owner: dict, session_id: str, outcome: dict) -> bool:
        for attempt in owner["attempts"]:
            if attempt["session_id"] == session_id and attach_recovered(attempt, outcome):
                # Keep the laptop writer's revision and timestamps. Polling recovered-count detects
                # this additive change without making its next numbered upload stale.
                Store._write(db, owner)
                return True
        return False

    def reconcile(self, run_id: str, session_id: str, outcome: dict) -> bool:
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            row = db.execute("SELECT body FROM runs WHERE run_id=?", (run_id,)).fetchone()
            return self._add_recovery(db, json.loads(row[0]), session_id, outcome) if row else False

    def _check_previous(self, previous: dict, body: dict):
        if any(previous[key] != body[key] for key in MANIFEST_FIELDS):
            raise Conflict("run manifest is immutable")
        if previous["status"] != "running" and body["status"] == "running":
            raise Conflict("run status cannot regress")
        old_attempts = {a["attempt_id"]: a for a in previous["attempts"]}
        for attempt in body["attempts"]:
            before = old_attempts.get(attempt["attempt_id"])
            if before is None or (before["session_id"] and before["session_id"] != attempt["session_id"]):
                raise Conflict("attempt identity is immutable")
            preserve_recovered(before, attempt)
            imported_retry = (
                body["source"] == "imported"
                and before["score"] is None
                and attempt["status"] == "completed"
                and known_score(attempt["score"])
                and before["error"] == attempt["error"]
            )
            if before["status"] in {"completed", "failed"} and not imported_retry:
                if (
                    before["status"] != attempt["status"]
                    or before["score"] != attempt["score"]
                    or original_result(before["result"]) != original_result(attempt["result"])
                ):
                    raise Conflict("finished attempts are immutable")

    def upsert(self, run: Run) -> bool:
        body = run.model_dump()
        try:
            with self._connect() as db:
                db.execute("BEGIN IMMEDIATE")
                old = db.execute("SELECT revision, body FROM runs WHERE run_id=?", (run.run_id,)).fetchone()
                if old and old[0] >= run.revision:
                    previous = json.loads(old[1])
                    if all(previous[key] == body[key] for key in MANIFEST_FIELDS):
                        for attempt in body["attempts"]:
                            outcome = recovered_result(attempt)
                            if attempt["session_id"] and outcome:
                                self._add_recovery(db, previous, attempt["session_id"], outcome)
                    return False
                if old:
                    self._check_previous(json.loads(old[1]), body)
                sessions = [a["session_id"] for a in body["attempts"] if a["session_id"]]
                if len(set(sessions)) != len(sessions):
                    raise Conflict("duplicate arena session")
                replaced_imports = set()
                for attempt in body["attempts"]:
                    session = attempt["session_id"]
                    if not session:
                        continue
                    owner = db.execute(
                        "SELECT run_id FROM sessions WHERE arena=? AND session_id=?", (run.arena_url, session)
                    ).fetchone()
                    if not owner or owner[0] == run.run_id:
                        continue
                    owner_body = json.loads(
                        db.execute("SELECT body FROM runs WHERE run_id=?", (owner[0],)).fetchone()[0]
                    )
                    if run.source == "imported":
                        outcome = official_result(attempt)
                        if outcome:
                            self._add_recovery(db, owner_body, session, outcome)
                        return False
                    if owner_body["source"] != "imported" or len(owner_body["attempts"]) != 1:
                        raise Conflict("arena session already belongs to a run")
                    outcome = official_result(owner_body["attempts"][0])
                    if outcome:
                        attach_recovered(attempt, outcome)
                    replaced_imports.add(owner[0])
                # Preserve every official history outcome before restoring tracked provenance.
                # Later active/failure uploads inherit it without changing their original metrics.
                Run.model_validate(body)
                for owner_id in replaced_imports:
                    db.execute("DELETE FROM sessions WHERE run_id=?", (owner_id,))
                    db.execute("DELETE FROM runs WHERE run_id=?", (owner_id,))
                for session in sessions:
                    db.execute("INSERT OR IGNORE INTO sessions VALUES (?, ?, ?)", (run.arena_url, session, run.run_id))
                self._write(db, body)
        except ValueError as error:
            if isinstance(error, Conflict):
                raise
            raise Conflict("invalid or conflicting recovery evidence") from None
        return True

    def get(self, run_id: str) -> dict | None:
        with self._connect() as db:
            row = db.execute("SELECT body FROM runs WHERE run_id=?", (run_id,)).fetchone()
        return json.loads(row[0]) if row else None

    def all(self) -> list[Run]:
        with self._connect() as db:
            rows = db.execute("SELECT body FROM runs ORDER BY json_extract(body, '$.started_at') DESC").fetchall()
        return [Run.model_validate(json.loads(row[0])) for row in rows]

    def listing(self) -> dict:
        runs = self.all()
        quotas = [r.quota for r in runs if r.quota]
        latest = max(quotas, key=lambda q: timestamp(q.checked_at)) if quotas else None
        return {
            "runs": [summarize(run) for run in runs],
            "quota": latest.model_dump() if latest else None,
            "team": "y/agent",
        }

    def comparison(self, baseline: str, candidate: str) -> dict | None:
        left, right = self.get(baseline), self.get(candidate)
        return compare(Run.model_validate(left), Run.model_validate(right)) if left and right else None
"""Validate citations against stored original attempts, never narrative assertions."""


def validate_references(references, attempts):
    indexed = {a["attempt_id"]: a for a in attempts}
    for ref in references:
        if set(ref) - {"attempt_id", "supplier", "message_index"} or "attempt_id" not in ref:
            raise ValueError("invalid evidence reference")
        attempt = indexed.get(ref["attempt_id"])
        if attempt is None or attempt.get("status") == "pending":
            raise ValueError("evidence attempt unavailable")
        if "message_index" in ref and "supplier" not in ref:
            raise ValueError("message requires supplier")
        if "supplier" in ref:
            thread = attempt.get("threads", {}).get(ref["supplier"])
            if thread is None:
                raise ValueError("supplier evidence unavailable")
            if "message_index" in ref:
                messages = thread.get("messages", []) if isinstance(thread, dict) else thread
                index = ref["message_index"]
                if not isinstance(messages, list) or type(index) is not int or not 0 <= index < len(messages):
                    raise ValueError("message evidence unavailable")
    return references
"""One deterministic interleaving for the server plan and both local runners."""

import random


def campaign_order(cases, repetitions, seed, arms=("baseline", "candidate")):
    rng = random.Random(seed)
    cells = []
    for repeat in range(1, repetitions + 1):
        for case in cases:
            order = list(arms)
            rng.shuffle(order)
            cells.extend(dict(arm=arm, case_id=case, repeat=repeat) for arm in order)
    return cells

"""Transactional loop metadata; laptops execute code and report owned evidence."""

import json
import sqlite3
import time
from pathlib import Path

from .checkpoints import validate_checkpoint
from .evidence import validate_references
from .loop_models import (
    Campaign,
    Complete,
    Family,
    Finding,
    NotCreated,
    Outcome,
    Recommendation,
    Reconciliation,
    Start,
    Suite,
)
from .ordering import campaign_order
from .policy import evaluate_campaign
from .store import Conflict


class LoopStore:
    def __init__(self, path: Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS loop_records (
                    kind TEXT NOT NULL, id TEXT NOT NULL, body TEXT NOT NULL,
                    PRIMARY KEY(kind,id));
                CREATE TABLE IF NOT EXISTS loop_sessions (
                    arena TEXT NOT NULL, session_id TEXT NOT NULL, attempt_id TEXT NOT NULL,
                    PRIMARY KEY(arena,session_id));
                CREATE TABLE IF NOT EXISTS loop_leases (
                    key_id TEXT PRIMARY KEY, attempt_id TEXT, last_start REAL NOT NULL);
            """)

    def _connect(self):
        return sqlite3.connect(self.path, timeout=10)

    @staticmethod
    def _get(db, kind, key):
        row = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
        if not row:
            raise ValueError("record not found")
        return json.loads(row[0])

    @staticmethod
    def _all(db, kind):
        records = [
            json.loads(r[0]) for r in db.execute("SELECT body FROM loop_records WHERE kind=? ORDER BY id", (kind,))
        ]
        if kind == "history":
            records.sort(key=lambda event: (event["recommendation"]["updated_at"], event["event_id"]))
        return records

    @staticmethod
    def _put(db, kind, key, body, immutable=False):
        encoded = json.dumps(body, sort_keys=True, allow_nan=False)
        row = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
        if immutable and row and json.loads(row[0]) != body:
            raise Conflict("immutable record conflict")
        db.execute(
            "INSERT INTO loop_records VALUES(?,?,?) ON CONFLICT(kind,id) DO UPDATE SET body=excluded.body",
            (kind, key, encoded),
        )
        return body

    def _checkpoint(self, db, suite, key):
        checkpoint = self._get(db, "checkpoints", key)
        if (
            not checkpoint["published"]
            or checkpoint["runner"] != suite["runner"]
            or checkpoint["data"] != suite["data"]
        ):
            raise ValueError("checkpoint unavailable or execution inputs differ")
        return checkpoint

    def _practice(self, db, suite, family, quota, *, starting=False):
        if suite["environment"] != "practice":
            return
        if not family["practice_allowance"] or quota is None or not 0 <= time.time() - quota["observed_at"] <= 60:
            raise ValueError("practice allowance and fresh quota required")
        campaigns = self._all(db, "campaigns")
        active = sum(
            sum(a["status"] == "pending" for a in c["attempts"])
            for c in campaigns
            if self._get(db, "suites", c["suite_id"])["arena_url"] == suite["arena_url"]
            and self._get(db, "suites", c["suite_id"])["environment"] == "practice"
        )
        required = 0 if starting else suite["max_sessions"]
        reserve = max([family["reserve"]] + [f["reserve"] for f in self._all(db, "families")])
        if quota["remaining"] - quota["open_sessions"] - active - required < reserve:
            raise ValueError("protected practice reserve")
        if not starting and family["practice_reserved"] + required > family["practice_allowance"]:
            raise ValueError("practice allowance exhausted")

    def write(self, operation: str, body: dict) -> dict:
        models = {
            "suite": Suite,
            "family": Family,
            "campaign": Campaign,
            "seed": Recommendation,
            "restore": Recommendation,
            "attempt-start": Start,
            "attempt-result": Outcome,
            "attempt-reconcile": Reconciliation,
            "attempt-not-created": NotCreated,
            "complete": Complete,
            "finding": Finding,
        }
        if operation == "checkpoint":
            body = validate_checkpoint(body)
        elif operation in models:
            body = models[operation].model_validate(body).model_dump()
        else:
            raise ValueError("unknown operation")
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            if operation in ("checkpoint", "suite", "family"):
                kind = {"checkpoint": "checkpoints", "suite": "suites", "family": "families"}[operation]
                key = body[operation + "_id"]
                if operation == "family":
                    body.update(reserved_sessions=0, practice_reserved=0)
                    existing = db.execute("SELECT body FROM loop_records WHERE kind=? AND id=?", (kind, key)).fetchone()
                    if existing:
                        old = json.loads(existing[0])
                        body.update(
                            reserved_sessions=old["reserved_sessions"], practice_reserved=old["practice_reserved"]
                        )
                return self._put(db, kind, key, body, immutable=True)
            if operation in ("seed", "restore"):
                suite = self._get(db, "suites", body["suite_id"])
                self._checkpoint(db, suite, body["checkpoint_id"])
                if operation == "restore" and not body["request_id"]:
                    raise ValueError("restore request ID required")
                if operation == "restore" and not any(
                    h["suite_id"] == body["suite_id"] and h["checkpoint_id"] == body["checkpoint_id"]
                    for h in self._all(db, "history")
                ):
                    raise ValueError("restore target was never recommended")
                event_id = body["request_id"] or "seed:" + body["suite_id"]
                previous_event = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("history", event_id)
                ).fetchone()
                if previous_event:
                    event = json.loads(previous_event[0])
                    if event.get("request") != body:
                        raise Conflict("recommendation request conflict")
                    return event["recommendation"]
                old = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("recommended", body["suite_id"])
                ).fetchone()
                old = json.loads(old[0]) if old else None
                if (
                    operation == "seed"
                    and old
                    or operation == "restore"
                    and (not old or body["generation"] != old["generation"])
                ):
                    raise Conflict("recommendation generation conflict")
                return self._recommend(db, suite, body["checkpoint_id"], old, event_id, operation, request=body)
            if operation == "campaign":
                previous = db.execute(
                    "SELECT body FROM loop_records WHERE kind=? AND id=?", ("campaigns", body["campaign_id"])
                ).fetchone()
                if previous:
                    previous = json.loads(previous[0])
                    if previous["request"] != body:
                        raise Conflict("campaign ID conflict")
                    return previous
                suite = self._get(db, "suites", body["suite_id"])
                family = self._get(db, "families", body["family_id"])
                rec = self._get(db, "recommended", body["suite_id"])
                if rec["generation"] != body["generation"] or rec["checkpoint_id"] != body["baseline_id"]:
                    raise Conflict("baseline superseded")
                for key in ("baseline_id", "candidate_id"):
                    self._checkpoint(db, suite, body[key])
                if family["reserved_sessions"] + suite["max_sessions"] > family["max_sessions"]:
                    raise ValueError("family budget exhausted")
                self._practice(db, suite, family, body["quota"])
                attempts = []
                for cell in campaign_order(suite["cases"], suite["repetitions"], body["seed"]):
                    arm, case, repeat = cell["arm"], cell["case_id"], cell["repeat"]
                    case_index = suite["cases"].index(case)
                    attempts.append(
                        dict(
                            attempt_id=f"{body['campaign_id']}:{case_index}:{repeat}:{arm}",
                            **cell,
                            checkpoint_id=body[arm + "_id"],
                            status="pending",
                        )
                    )
                family["reserved_sessions"] += suite["max_sessions"]
                if suite["environment"] == "practice":
                    family["practice_reserved"] += suite["max_sessions"]
                self._put(db, "families", family["family_id"], family)
                campaign = {
                    **body,
                    "request": body,
                    "attempts": attempts,
                    "status": "running",
                    "created_at": time.time(),
                }
                return self._put(db, "campaigns", body["campaign_id"], campaign)
            if operation == "attempt-not-created":
                campaign, attempt = self._attempt(db, body["attempt_id"])
                if "start" not in attempt or attempt["checkpoint_id"] != body["checkpoint_id"]:
                    raise ValueError("not-created attempt mismatch")
                if attempt["start"]["request"]["worker_id"] != body["worker_id"]:
                    raise Conflict("not-created evidence executor mismatch")
                if attempt.get("session_id") or attempt.get("reconciliation"):
                    raise Conflict("known session cannot be declared not created")
                if "not_created" in attempt:
                    if attempt["not_created"] != body:
                        raise Conflict("immutable not-created evidence conflict")
                    return attempt
                if attempt["status"] not in ("started", "failed"):
                    raise Conflict("not-created evidence requires started or failed attempt")
                attempt.update(status="failed", not_created=body)
                db.execute("UPDATE loop_leases SET attempt_id=NULL WHERE attempt_id=?", (body["attempt_id"],))
                self._put(db, "campaigns", campaign["campaign_id"], campaign)
                return attempt
            if operation in ("attempt-start", "attempt-result", "attempt-reconcile"):
"""Strict public loop records, independent of execution and transport."""

from typing import Any, Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .models import check_json

ID = str


class Record(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, allow_inf_nan=False)

    @model_validator(mode="after")
    def safe_json(self):
        check_json(self.model_dump())
        for name, value in self.model_dump().items():
            if name.endswith("_id") and value is not None:
                import re

                if not re.fullmatch(r"[A-Za-z0-9_.:-]{1,240}", value):
                    raise ValueError("invalid identity")
        return self


class Policy(Record):
    version: str = "v1"
    min_gain: float = Field(default=1.0, ge=1)
    max_case_regression: float = Field(default=2.0, ge=0, le=2)
    min_win_fraction: float = Field(default=2 / 3, ge=2 / 3, le=1)


class Suite(Record):
    suite_id: ID
    cases: list[str] = Field(min_length=1, max_length=100)
    repetitions: int = Field(ge=3, le=100)
    runner: Literal["serial", "async"]
    arena_url: str
    environment: Literal["sandbox", "practice", "simulator"]
    data: dict[str, Any]
    max_sessions: int = Field(ge=1, le=20000)
    policy: Policy

    @model_validator(mode="after")
    def coherent(self):
        url = urlsplit(self.arena_url)
        if (
            url.scheme not in ("https", "http")
            or not url.hostname
            or url.username
            or url.password
            or url.query
            or url.fragment
        ):
            raise ValueError("invalid arena origin")
        if url.path not in ("", "/") or len(set(self.cases)) != len(self.cases):
            raise ValueError("invalid cases or arena origin")
        if self.max_sessions != 2 * len(self.cases) * self.repetitions:
            raise ValueError("session ceiling differs from exact plan")
        # HTTP origin aliases must share quota reservations and session ownership.
        host = url.hostname.lower()
        if ":" in host:
            host = "[" + host + "]"
        port = url.port
        suffix = "" if port is None or port == {"http": 80, "https": 443}[url.scheme] else f":{port}"
        self.arena_url = f"{url.scheme}://{host}{suffix}"
        return self


class Family(Record):
    family_id: ID
    max_sessions: int = Field(ge=1, le=100000)
    practice_allowance: int = Field(default=0, ge=0)
    reserve: int = Field(default=0, ge=0)


class Quota(Record):
    remaining: int = Field(ge=0)
    observed_at: float = Field(ge=0)
    open_sessions: int = Field(default=0, ge=0)


class Campaign(Record):
    campaign_id: ID
